    const out = git(cwd, ["diff", "--no-color"]);
    if (out.trim()) return reply("diff", out.trimEnd(), true, { format: "diff" });
    // `git diff` shows unstaged edits to tracked files only; say what else is uncommitted rather than calling it clean.
